-- CT-03b: audited, deny-first, finite-scope staff permission exceptions.
-- STAGED ONLY. File name generated by Supabase CLI 3.2.0 in Actions #45318371778.
-- Requires previously staged CT-02b and CT-02c; DO NOT apply to hosted Clear Talks
-- before owner bootstrap, DB + Storage restore rehearsal, migrated schema
-- history reconciliation, negative tests, and explicit release authorization.
begin;

-- A constrained override protects high-impact identity/administrative privileges
-- against bypass via 'allow' (or an accidental administrative 'deny'). Managing
-- these requires built-in roles, not capability exceptions.
create function public.staff_guard_capability_override()
returns trigger language plpgsql security invoker set search_path = ''
as $fn$
declare
  v_member uuid;
  v_cap public.staff_capability_key;
  v_is_owner boolean;
begin
  perform pg_catalog.pg_advisory_xact_lock(202611,2302);

  if tg_op='DELETE' then
    v_member:=old.membership_id;
    v_cap:=old.capability_key;
  else
    v_member:=new.membership_id;
    v_cap:=new.capability_key;
  end if;
  if v_cap::text like 'team.%'
    or v_cap in (
      'settings.security_admin'::public.staff_capability_key,
      'reader.personal'::public.staff_capability_key,
      'newsroom.access'::public.staff_capability_key
    ) then
    raise exception 'Administrative/entry/personal access cannot be overridden'
      using errcode='42501';
  end if;

  select exists(
    select 1 from public.staff_member_roles r
    join public.staff_role_presets p on p.id=r.role_preset_id
    where r.membership_id=v_member and p.role_key='owner'
  ) into v_is_owner;
  if v_is_owner then
    raise exception 'Owner membership cannot receive permission exceptions'
      using errcode='42501';
  end if;

  if tg_op='DELETE' then return old; end if;
  if tg_op='UPDATE' then
    if new.id is distinct from old.id
      or new.membership_id is distinct from old.membership_id
      or new.capability_key is distinct from old.capability_key
      or new.scope is distinct from old.scope
      or new.created_at is distinct from old.created_at then
      raise exception 'Override identity and scope cannot be reassigned'
        using errcode='42501';
    end if;
  end if;

  if new.effect not in ('allow','deny') or new.scope not in ('all','assigned','own')
    or pg_catalog.length(pg_catalog.btrim(new.reason)) < 12
    or pg_catalog.length(new.reason)>500 or new.granted_by is null then
    raise exception 'Override fields/reason are invalid'
      using errcode='22023';
  end if;
  if new.effect='allow' then
    if new.expires_at is null or new.expires_at<now()+interval '1 hour'
      or new.expires_at>now()+interval '90 days' then
      raise exception 'Allow overrides must expire within 1h to 90d'
        using errcode='22023';
    end if;
  elsif new.expires_at is not null and
    (new.expires_at<=now() or new.expires_at>now()+interval '365 days') then
    raise exception 'Deny exception expiration is invalid'
      using errcode='22023';
  end if;
  return new;
end;
$fn$;

create trigger staff_capability_override_guard
before insert or update or delete on public.staff_capability_overrides
for each row execute function public.staff_guard_capability_override();

revoke all on function public.staff_guard_capability_override()
from public,anon,authenticated;
grant execute on function public.staff_guard_capability_override() to service_role;

-- Executed solely through the trusted, server-side service_role client
-- after it verifies auth.getUser() and current team.manage_overrides.
-- SECURITY INVOKER; explicitly recheck real active, nonexpiring owner actor
-- in PostgreSQL under the same advisory lock as existing CT-02c grants.
-- The existing after-change trigger writes a transactionally linked audit.
create function public.staff_apply_override_change(
  p_actor_auth_user_id uuid,
  p_target_membership_id uuid,
  p_operation text,
  p_capability text,
  p_scope text,
  p_effect text,
  p_expires_at timestamptz,
  p_reason text,
  p_request_id uuid
)
returns uuid language plpgsql security invoker set search_path = ''
as $fn$
declare
  v_cap public.staff_capability_key;
  v_target_auth_user_id uuid;
  v_count int;
begin
  if p_actor_auth_user_id is null or p_target_membership_id is null
    or p_request_id is null or p_operation not in ('set','remove')
    or p_scope not in ('all','assigned','own')
    or p_reason is null or pg_catalog.length(pg_catalog.btrim(p_reason))<12
    or pg_catalog.length(p_reason)>500
    or p_capability is null then
    raise exception 'Invalid override mutation request'
      using errcode='22023';
  end if;

  -- Fail closed on unknown capabilities, before casting to the enum type.
  if not exists(select 1 from pg_catalog.pg_enum e
    join pg_catalog.pg_type t on t.oid=e.enumtypid
    join pg_catalog.pg_namespace n on n.oid=t.typnamespace
    where n.nspname='public' and t.typname='staff_capability_key'
      and e.enumlabel=p_capability) then
    raise exception 'Unrecognized staff capability' using errcode='22023';
  end if;
  v_cap:=p_capability::public.staff_capability_key;
  if v_cap::text like 'team.%'
    or v_cap in (
      'settings.security_admin'::public.staff_capability_key,
      'reader.personal'::public.staff_capability_key,
      'newsroom.access'::public.staff_capability_key
    ) then
    raise exception 'Administrative, entry and reader permissions require roles'
      using errcode='42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(202611,2302);
  if not exists(
    select 1 from public.staff_memberships m
    join public.staff_member_roles r on r.membership_id=m.id
    join public.staff_role_presets p on p.id=r.role_preset_id
    where m.auth_user_id=p_actor_auth_user_id
      and m.status='active' and m.expires_at is null
      and m.member_type='employee' and p.role_key='owner'
      and r.expires_at is null
  ) then
    raise exception 'Only a current active owner can change staff overrides'
      using errcode='42501';
  end if;

  select auth_user_id into v_target_auth_user_id
  from public.staff_memberships
  where id=p_target_membership_id for update;
  if not found then
    raise exception 'Target staff membership not found' using errcode='P0002';
  end if;
  if v_target_auth_user_id=p_actor_auth_user_id
    or exists (
      select 1 from public.staff_member_roles r
      join public.staff_role_presets p on p.id=r.role_preset_id
      where r.membership_id=p_target_membership_id
        and p.role_key='owner'
    ) then
    raise exception 'Owner/self overrides are forbidden'
      using errcode='42501';
  end if;

  perform pg_catalog.set_config('app.staff_actor_auth_id',p_actor_auth_user_id::text,true);
  perform pg_catalog.set_config('app.staff_request_id',p_request_id::text,true);
  perform pg_catalog.set_config('app.staff_reason',p_reason,true);

  if p_operation='set' then
    if p_effect not in ('allow','deny') then
      raise exception 'Override requires allow or deny effect' using errcode='22023';
    end if;
    -- The hard table trigger repeats these constraints, even when accessed
    -- directly by other privileged database clients.
    if p_effect='allow' and (
      p_expires_at is null
      or p_expires_at < now()+interval '1 hour'
      or p_expires_at > now()+interval '90 days'
    ) then
      raise exception 'Allow exceptions must be time-bound' using errcode='22023';
    end if;
    insert into public.staff_capability_overrides (
      membership_id,capability_key,effect,scope,reason,granted_by,expires_at
    ) values (
      p_target_membership_id,v_cap,p_effect,p_scope,
      p_reason,p_actor_auth_user_id,p_expires_at
    )
    on conflict(membership_id,capability_key,scope)
    do update set effect=excluded.effect,reason=excluded.reason,
      granted_by=excluded.granted_by,expires_at=excluded.expires_at;
  else
    if p_effect is not null or p_expires_at is not null then
      raise exception 'Remove operation cannot supply effect or expiry'
        using errcode='22023';
    end if;
    delete from public.staff_capability_overrides
    where membership_id=p_target_membership_id
      and capability_key=v_cap and scope=p_scope;
    get diagnostics v_count=row_count;
    if v_count<>1 then
      raise exception 'No matching override to remove'
        using errcode='P0002';
    end if;
  end if;
  return p_request_id;
end;
$fn$;

revoke all on function public.staff_apply_override_change(
  uuid,uuid,text,text,text,text,timestamptz,text,uuid
) from public,anon,authenticated;
grant execute on function public.staff_apply_override_change(
  uuid,uuid,text,text,text,text,timestamptz,text,uuid
) to service_role;
commit;
